window.__BUNDLE__={"generatedAt":"2026-11-10T23:45:00.838654+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-11-03","archiveCutoff":"2021-11-11","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":256,"arxiv":1396,"total":1652},"freshness":{"latestPaperDate":"2026-11-10","latestPublishedDate":"2026-11-10","latestBatchCount":600,"newInLast24h":664,"newInLast48h":934},"historyTotal":31818,"topicCounts":{"Multi-Agent":3297,"Evaluation":17509,"Planning":2299,"Memory":620,"Code Agent":1274,"Interpretability":1063,"Agentic RAG":1619,"Agentic Search":2181,"RL for LLM":1648,"Reasoning":8390,"Hallucination":1344,"Post-Training":3474,"Alignment":4095,"World Model":636,"Tool Use":1505,"Agent Safety":2827,"Computer Use":408,"Reflection":1141,"VLM Training":2524,"LLM Training":4093,"Fine-tuning":4935,"Multimodal Agent":182,"Agent Framework":997,"Error Attribution":194,"Data Engine":639},"count":36,"recentTotal":2572,"archiveCount":0,"archiveTotal":29246,"sources":{"hf":53,"arxiv":2519,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"hfUrl":"https://huggingface.co/papers/2611.10771","id":"arxiv:2611.10771","source":"hf","title":"WorldFoundry: Towards Unified Infrastructure for World Intelligence","tags":["Evaluation","World Model"],"upvotes":53,"authors":["Juanxi Tian","Jiadong Hou","Baiang Li","Xin Lin","Zhengbo Jiao","Weijia Zhang","Yeying Jin","Truong Nguyen","Haitian Zheng","Zhifei Zhang","Jianfei Yang","Ming-Hsuan Yang","Felix Heide","Wei Xiong","Enze Xie","Wanhua Li"],"pdf":"https://arxiv.org/pdf/2611.10771.pdf","arxiv":"https://arxiv.org/abs/2611.10771","url":"https://arxiv.org/abs/2611.10771","announceDate":"2026-11-10","submittedDate":"2026-11-07","topics":["Evaluation","World Model"],"date":"2026-11-10","abstract":"Visual generative models increasingly blur the line between synthesizing observations and simulating environments. Yet visual plausibility alone does not constitute successful world modeling: compelling outputs may lack persistent state, physical dynamics, or causally consistent responses to interactions. We define a generative world model as a predictive dynamical system that maintains a persistent, history-conditioned representation of an environment, updates that representation in response to actions or interventions, and generates temporally coherent trajectories that reflect outcomes under observed and counterfactual interventions. From this definition, we derive an intelligence-oriented framework spanning perceptual grounding, persistent state modeling, controllable transformation, dynamics-aware prediction, and closed-loop interaction. We present WorldFoundry, open-source infrastr"},{"hfUrl":"https://huggingface.co/papers/2611.12762","id":"arxiv:2611.12762","source":"hf","title":"Sage-Taiyi: A Metacognitive Architecture for Scientific Discovery","tags":["Reasoning","Evaluation"],"upvotes":51,"authors":["Weida Wang","Benteng Chen","Yigeng Jiang","Shuchen Pu","Weiping Shen","Zichao Liu","Yulin Su","Zitong Wang","Siyu Zhou","Zifu Wang","Yizhi Li","Xin Zong","Yuning Yang","Jixiang Bi","Yuan Wang","Chuyi Peng","Shiyao Geng","Qi Zhang","Kuan Lu","Mengzhu Li","Weiwang Xu","Peishan Xiang","Chengjun Liu","Chengrui Wei","Fangchen Yu","Shengji Tang","Yichen Jiang","Jingqi Ye","Cheng Yang","Tao Hu","Jianbiao Mei","Qinglong Cao","Kun Li","Yixin Chen","Shengyuan Xu","Juncheng Xiao","Yiheng Wang","Ruizhe Chen","Shiyang Feng","Runmin Ma","Xiangchao Yan","Zongsheng Cao","Haomeng Hu","Yu Ke","Taihui Wu","Meng Dai","Xu Guo","Haoyang Peng","Yinglong Ni","Pingsen Shi","Xiaosong Wang","Shuyue Hu","Haijun Li","Sherry Dongqi Bao","Yang Yang","Chao Yang","Jie Hou","Tianfan Fu","Yi Gong","Jin Zeng","Mao Su","Hongxia Hao","Fanyang Mo","Fenghua Ling","Tianshu Yu","Yunqi Cai","Baihong Chi","Jingwei Wang","Lei Wang","Chuncheng Bu","Shide Lv","Guangyu Wang","Yuqiang Li","Chunfeng Song","Lei Bai","Hui Wang","Xujun Fu","Li Cao","Lei Chen","Dahua Lin","Xing Xie","Bowen Zhou","Wenlong Zhang","Pinlong Cai","Peng Ye","Aiwen Lei","Jie Li","Shengchun Wang","Bo Zhang","Shufei Zhang"],"pdf":"https://arxiv.org/pdf/2611.12762.pdf","arxiv":"https://arxiv.org/abs/2611.12762","url":"https://arxiv.org/abs/2611.12762","announceDate":"2026-11-10","submittedDate":"2026-11-09","topics":["Reasoning","Evaluation"],"date":"2026-11-10","abstract":"We introduce Sage-Taiyi, a metacognition-inspired architecture that uses accumulated scientific understanding to guide what to investigate next and how to investigate it. Through explicit monitoring and control, the system revises its understanding of evidence, assumptions, and unresolved questions, then uses these assessments to adapt research targets and select reusable reasoning methods. On Taiyi-Bench, an AI co-scientist ideation benchmark comprising 265 tasks from 50 papers across ten disciplines, Sage-Taiyi ranks first on all eight metrics of historical rediscovery and open-ended ideation, achieving an Overall score of 54.0 compared with 47.9 for the strongest baseline, AI Scientist-v2. It also performs well on two external scientific ideation benchmarks. Five expert-guided collaborations further connect its proposals to experimental and computational validation across chemistry, m"},{"hfUrl":"https://huggingface.co/papers/2611.10329","id":"arxiv:2611.10329","source":"hf","title":"SIRIS: Can LLMs Tell When Simulation Errors Matter in AI-Driven Systems Research","tags":["Reflection"],"upvotes":12,"authors":["Jinwoo Hwang","Sukmin Cho","Tao Zhang","Soheil Abbasloo","Jongse Park","Peng Cheng"],"pdf":"https://arxiv.org/pdf/2611.10329.pdf","arxiv":"https://arxiv.org/abs/2611.10329","url":"https://arxiv.org/abs/2611.10329","announceDate":"2026-11-10","submittedDate":"2026-11-06","topics":["Reflection"],"date":"2026-11-10","abstract":"LLM agents increasingly drive systems research and rely on simulators to evaluate candidate designs at scale. Simulators are imperfect by design: their modeling limitations can distort predictions yet leave the recommended design correct, or change which design should be selected. We introduce Siris to test whether LLMs can tell these cases apart, judging from their systems understanding when a limitation invalidates the simulator's recommendation. By perturbing a simulator, Siris constructs workload pairs with the same candidates, limitation, and simulator recommendation. The perturbation changes predictions on both workloads, yet a reference simulator supports the recommendation on only one. Evaluating thirteen frontier LLMs on LLM serving design problems, we find that identifying a limitation does not ensure a correct choice, and even the strongest models sometimes abandon valid recom"},{"hfUrl":"https://huggingface.co/papers/2611.10404","id":"arxiv:2611.10404","source":"hf","title":"Coding or Cheating? An Investigation of Frontier Coding LLMs","tags":["Evaluation"],"upvotes":5,"authors":["Yuntao Gui"],"pdf":"https://arxiv.org/pdf/2611.10404.pdf","arxiv":"https://arxiv.org/abs/2611.10404","url":"https://arxiv.org/abs/2611.10404","announceDate":"2026-11-10","submittedDate":"2026-11-07","topics":["Evaluation"],"date":"2026-11-10","abstract":"Frontier agentic LLMs are trained on verifiable rewards in reinforcement learning (RL) environments built from real software repositories. A passing test suite is treated as the reward for solving the task. We show that, on hard problems, frontier models often satisfy these rewards by obtaining the answer instead of deriving it, known as reward hacking. Prior reports document this behavior on public benchmarks. We test its persistence on unseen problems. In a hardened environment where the answer cannot leak, nearly every model we tested attempted to recover the answer, escalating through tiers of increasingly specialized exploitation: mining the repository history for the upstream fix, inspecting the git object store directly, and sweeping the filesystem for a possible newer copy of the source or hidden tests. These attempts were concentrated on the hardest problems, and the models diff"},{"hfUrl":"https://huggingface.co/papers/2611.12324","id":"arxiv:2611.12324","source":"hf","title":"How Many Exposures Does a World Model Need? Learning Unseen Game Mechanics at Test Time","tags":["Evaluation","World Model"],"upvotes":4,"authors":["Ku Onoda","Haruto Kawano","Shota Takashiro","Kohei Hayashi"],"pdf":"https://arxiv.org/pdf/2611.12324.pdf","arxiv":"https://arxiv.org/abs/2611.12324","url":"https://arxiv.org/abs/2611.12324","announceDate":"2026-11-10","submittedDate":"2026-11-09","topics":["Evaluation","World Model"],"date":"2026-11-10","abstract":"World models enable agents to plan and learn from imagined experience, but in an unfamiliar environment they must learn its mechanics from limited interaction. A mechanic is a rule for how an action or an interaction changes part of the environment. Each occurrence of a mechanic that the model observes is one exposure. We ask how many exposures a world model needs to predict the effects of a new environment's mechanics. We address this question on ARC-AGI-3, a benchmark of interactive games defined by their programs. We introduce MechEval, which labels 69 recurring mechanics across 20 games from these programs. It scores each prediction on the cells the mechanic changes at each exposure. As a test bed, we build WARC (World model for ARC-AGI-3), a 35M-parameter vision transformer that is pretrained on other games and updates all of its parameters after each transition. On held-out games, "},{"hfUrl":"https://huggingface.co/papers/2611.11890","id":"arxiv:2611.11890","source":"hf","title":"Training Vision Transformers to Focus: Emergence of Spatial Attention Head Specialization","tags":["Interpretability"],"upvotes":4,"authors":["Yuji Nozawa","Yu-Chieh Lin","Youyang Ng"],"pdf":"https://arxiv.org/pdf/2611.11890.pdf","arxiv":"https://arxiv.org/abs/2611.11890","url":"https://arxiv.org/abs/2611.11890","announceDate":"2026-11-10","submittedDate":"2026-11-09","topics":["Interpretability"],"date":"2026-11-10","abstract":"Self-supervised learning in Vision Transformer models, such as DINO, enables robust visual perception without requiring labeled data by leveraging large-scale image datasets. However, these models lack a focusing mechanism during training, resulting in perceptual representations that are often ambiguous or overly similar. In this work, we introduce two visual focusing loss functions designed to establish correspondence between the model's attention and specific regions within images. Specifically, we leverage the multi-head attention mechanism within the model to selectively steer the model's focus, leading to the emergence of spatial attention head specialization, characterized by diverse and spatially focused perceptual capabilities without requiring annotations. Through both qualitative and quantitative evaluations, we demonstrate that our method substantially increases the spatial se"},{"hfUrl":"https://huggingface.co/papers/2501.08686","id":"arxiv:2501.08686","source":"hf","title":"Knowledge Graph-based Retrieval-Augmented Generation for Schema Matching","tags":["Agentic RAG","Agentic Search","Hallucination"],"upvotes":1,"authors":["Chuangtao Ma","Sriom Chakrabarti","Arijit Khan","Bálint Molnár"],"pdf":"https://arxiv.org/pdf/2501.08686.pdf","arxiv":"https://arxiv.org/abs/2501.08686","url":"https://arxiv.org/abs/2501.08686","topics":["Agentic RAG","Agentic Search","Hallucination"],"date":"2026-11-10","abstract":"Traditional similarity-based schema matching methods fail to resolve semantic ambiguities and conflicts in complex, domain-specific mappings due to a lack of commonsense and domain-specific knowledge. In parallel, large language models (LLMs) without sufficient background knowledge tend to hallucinate, further complicating schema matching. To overcome these limitations, we introduce KG-RAG4SM, a Knowledge Graph-based Retrieval-Augmented Generation for Schema Matching. This method integrates novel retrieval mechanisms, including LLM-based, vector-based, graph traversal-based, and hybrid techniques with advanced reranking schemes to extract the most relevant subgraphs from large external KGs. Our approach achieves superior results without requiring re-training, as evidenced by improvements of 39.79% in precision and 30.56% in F1 score over LLM-based state-of-the-art (SOTA) methods (e.g., J"},{"hfUrl":"https://huggingface.co/papers/2611.12875","id":"arxiv:2611.12875","source":"hf","title":"Click3R: Interactive Stereo 3D Reconstruction with Sparse Correspondence Clicks","tags":["Evaluation"],"upvotes":1,"authors":["Hao Gu","Jin Yao","Zezhou Cheng"],"pdf":"https://arxiv.org/pdf/2611.12875.pdf","arxiv":"https://arxiv.org/abs/2611.12875","url":"https://arxiv.org/abs/2611.12875","announceDate":"2026-11-10","submittedDate":"2026-11-09","topics":["Evaluation"],"date":"2026-11-10","abstract":"Despite impressive progress, existing feed-forward large 3D reconstruction models produce a single, irrevocable prediction. When these models fail, there is no mechanism to correct their mistakes. To address this limitation, we introduce Click3R, a framework for interactive geometric correction of feed-forward models using sparse human correspondence clicks. Given an image pair and a small set of cross-view point correspondences provided by a user, Click3R injects geometric constraints into the 3D reconstruction networks through a lightweight point correspondence adapter, enabling the model to resolve ambiguities in challenging scenarios such as repetitive textures, symmetric structures, large viewpoint changes, or textureless regions. To evaluate interactive reconstruction, we curate a challenging benchmark specifically designed to expose failure modes of existing feed-forward 3D recons"},{"hfUrl":"https://huggingface.co/papers/2611.12886","id":"arxiv:2611.12886","source":"arxiv","title":"Reframe: Observation-Aligned Multi-Teacher On-Policy Distillation for Agentic Visual Reasoning","tags":["Post-Training","LLM Training","Tool Use","Reasoning","Evaluation"],"upvotes":37,"authors":["Haozhi Yuan","Handong Li","Yifan Zhang","Qianshan Wei"],"pdf":"https://arxiv.org/pdf/2611.12886.pdf","arxiv":"https://arxiv.org/abs/2611.12886","url":"https://arxiv.org/abs/2611.12886","announceDate":"2026-11-10","submittedDate":"2026-11-09","topics":["Post-Training","LLM Training","Tool Use","Reasoning","Evaluation","Alignment","Multimodal Agent"],"date":"2026-11-10","abstract":"Agentic reinforcement learning (RL) and multi-teacher on-policy distillation (MOPD) offer complementary routes to post-training. For visual agents, however, tool use presents two related challenges. Models may overlook useful tool-returned observations, while poorly grounded actions can limit the evidence available for subsequent distillation. We introduce Reframe, a post-training framework that treats the observation state, rather than only the output distribution, as an object of alignment. First, Ground-Drop-GRPO (GD-GRPO) trains spatial and temporal specialists with evidence-aware rewards and stochastic removal of the original visual input, encouraging them to acquire grounded evidence and use the returned observations. Second, Observation-Gated-MOPD (OG-MOPD) replaces deficient tool actions with canonical ones mid-rollout and resumes distillation from the repaired observation. The t"},{"hfUrl":"https://huggingface.co/papers/2611.10304","id":"arxiv:2611.10304","source":"arxiv","title":"Longtail-SWE: High-Quality SWE Tasks for Underrepresented Languages","tags":["Evaluation"],"upvotes":19,"authors":["Vladimir Dobrovolskii","Ibragim Badertdinov","Alexander Golubev"],"pdf":"https://arxiv.org/pdf/2611.10304.pdf","arxiv":"https://arxiv.org/abs/2611.10304","url":"https://arxiv.org/abs/2611.10304","announceDate":"2026-11-10","submittedDate":"2026-11-06","topics":["Evaluation"],"date":"2026-11-10","abstract":"Challenging repository-level benchmarks remain limited for many programming language ecosystems, where filtering scarce candidates with ambiguous descriptions or defective tests can discard valuable engineering problems. We introduce Longtail-SWE, a benchmark of 202 issue-resolution tasks across 13 languages with limited coverage in existing repository-level benchmarks: Clojure, Dart, Elixir, Erlang, F#, Haskell, Julia, Kotlin, Lua, OCaml, R, Scala, and Swift. Its construction uses a solver--judge--repairer pipeline: a solver attempts each candidate task, and a judge reviews the task together with the solver's trajectory and test results to guide revisions to tests and task descriptions. These revisions aim to correct tests that reject valid alternative implementations or accept incorrect solutions while retaining challenging tasks and preserving their intended requirements. We evaluate "},{"hfUrl":"https://huggingface.co/papers/2611.11558","id":"arxiv:2611.11558","source":"arxiv","title":"InfraRSI: Harnessing Recursive Self-Improvement for Training Infrastructure","tags":["LLM Training","Code Agent","Reflection"],"upvotes":14,"authors":["InfraRSI Team","Yuchuan Tian","Haocheng Mei","Ye Yuan","Chao Xu","Boxun Li","Guohao Dai","Kai Han","Allen Chen","Yunhe Wang","Yu Wang"],"pdf":"https://arxiv.org/pdf/2611.11558.pdf","arxiv":"https://arxiv.org/abs/2611.11558","url":"https://arxiv.org/abs/2611.11558","announceDate":"2026-11-10","submittedDate":"2026-11-08","topics":["LLM Training","Code Agent","Reflection"],"date":"2026-11-10","abstract":"While Recursive Self-Improvement (RSI) accelerates isolated algorithm and kernel synthesis, distributed LLM training depends on tightly coupled launch settings, operator kernels, and communication schedules, where single edits often hit out-of-memory (OOM) boundaries, compiler conflicts, measurement jitter, or silent numerical drift. We present InfraRSI, the agentic harness that turns open-ended human commands into verified training optimizations via a five-stage workflow: init locks editable scope and a fixed task contract over workload, loss, and timing invariants to prevent reward hacking, doctor profiles baseline phases and calibrates cluster noise, run co-optimizes launch knobs and code patches before re-verifying top candidates against the baseline and logging findings to a cross-hardware experience bank, and report and apply audit source paths, track failed-trial costs, and commit"},{"hfUrl":"https://huggingface.co/papers/2611.10592","id":"arxiv:2611.10592","source":"arxiv","title":"MotionGraphicsBench: Evaluating Motion Graphics Generation with Programmatic Verification","tags":["VLM Training","Multi-Agent","Reasoning","Evaluation"],"upvotes":7,"authors":["Jiaju Ma","Ashvini Kumar Jindal","Chuhua Wang","Sumithra Bhakthavatsalam"],"pdf":"https://arxiv.org/pdf/2611.10592.pdf","arxiv":"https://arxiv.org/abs/2611.10592","url":"https://arxiv.org/abs/2611.10592","announceDate":"2026-11-10","submittedDate":"2026-11-07","topics":["VLM Training","Multi-Agent","Reasoning","Evaluation"],"date":"2026-11-10","abstract":"Large language models can generate motion graphics from static images and natural language requests, but it remains difficult to evaluate how well models can follow requests that combine spatial, appearance, and temporal requirements. We introduce MotionGraphicsBench, an expert-curated benchmark of 100 instances for animating an input static SVG with a motion edit prompt. By supplying all required visual elements, our editing task reflects a designer-like workflow and isolates motion generation from graphic generation. Derived from real-world Lottie motion designs, our benchmark contains diverse combinations of spatio-temporal animation behaviors. Each benchmark instance pairs its model input with a deterministic, human-readable verification program that accepts different valid implementations and reports which prompt requirements pass or fail, rather than comparing against a reference a"},{"hfUrl":"https://huggingface.co/papers/2611.11344","id":"arxiv:2611.11344","source":"arxiv","title":"Spatial Harness: Grounding Spatial Reasoning in Executable World States with Physics Engines","tags":["VLM Training","Reasoning"],"upvotes":2,"authors":["Chentao Cao","Zhanke Zhou","Sangni Duan","Bo Han","Hang Li"],"pdf":"https://arxiv.org/pdf/2611.11344.pdf","arxiv":"https://arxiv.org/abs/2611.11344","url":"https://arxiv.org/abs/2611.11344","announceDate":"2026-11-10","submittedDate":"2026-11-08","topics":["VLM Training","Reasoning"],"date":"2026-11-10","abstract":"Spatial reasoning requires understanding how objects and observers are arranged in a scene and how their relations change with viewpoint or movement. Vision-language models (VLMs) typically perform both steps through model-internal reasoning, forming an implicit scene interpretation from partial views and imagining the consequences of spatial transformations. A misread scene can lead to a wrong answer, while even a correct interpretation does not ensure that imagined transformations satisfy spatial constraints. We introduce Spatial Harness, which represents scenes as explicit and executable world states to ground spatial reasoning in physics-engine feedback. A Perceiver integrates scene constraints extracted from the question with specialized visual estimates to place objects and cameras in a shared coordinate frame. The resulting state is instantiated in a physics engine, where a Reason"},{"hfUrl":"https://huggingface.co/papers/2611.12167","id":"arxiv:2611.12167","source":"arxiv","title":"FraudBench: A Legal Evaluation of AI Deception","tags":["Evaluation"],"upvotes":2,"authors":["Kevin Wei","Sumaya Nur Adan","Stephan Llerena","Mark Gitau","Jakob Merane","Anita Srinivasan","Colette Le Brannan","Keethan Kleiner","Alessandro Tacconelli","Michael Tiu","Case Thomason","Kyle Emili","Natasza Gadowska","Alex Mark","Eric Ren","Umang Bhatt","Jatinder Singh","Jacy Reese Anthis","Doni Bloomfield","Noam Kolt"],"pdf":"https://arxiv.org/pdf/2611.12167.pdf","arxiv":"https://arxiv.org/abs/2611.12167","url":"https://arxiv.org/abs/2611.12167","announceDate":"2026-11-10","submittedDate":"2026-11-09","topics":["Evaluation"],"date":"2026-11-10","abstract":"We introduce FraudBench, an evaluation of large language models' (LLMs) propensities to recommend, assist, or directly take actions that would constitute fraud under U.S. law. Our evaluation contains a novel dataset of 159 scenarios based on real-world U.S. court cases and validated by legal experts. We present each scenario to LLMs via three tasks at varying levels of autonomy: advising users, drafting messages for users to send, and acting directly on behalf of users (477 tasks total). In each scenario, FraudBench re-enacts the facts of a court case to give LLMs an opportunity, but no explicit instruction, to either misrepresent or conceal a material fact in a high-stakes commercial setting--e.g., whether to describe company-funded product testing as \"independent\" to customers (misrepresentation) or whether to hide unfavorable regulatory investigations from clients (concealment). We ev"},{"hfUrl":"https://huggingface.co/papers/2611.11740","id":"arxiv:2611.11740","source":"arxiv","title":"Creative Priming: Decoupling Process from Product to Escape the Creative Paradox","tags":["Post-Training"],"upvotes":2,"authors":["Alon Albalak","Sebastian Gabriel","David B. D'Ambrosio","Joel Lehman","Kenneth O. Stanley"],"pdf":"https://arxiv.org/pdf/2611.11740.pdf","arxiv":"https://arxiv.org/abs/2611.11740","url":"https://arxiv.org/abs/2611.11740","announceDate":"2026-11-10","submittedDate":"2026-11-09","topics":["Post-Training"],"date":"2026-11-10","abstract":"Many of the most consequential advances promised by AI, from curing diseases and inventing new technologies to formulating new scientific theories, are fundamentally creative acts. Yet creativity is uniquely difficult to learn because it faces a creative paradox: learning to repeat past examples of creative success makes those specific examples more likely to recur, inhibiting the very creativity desired. This work argues that creativity is better modeled as an explicit process rather than as a property of individual artifacts, and proposes to learn the underlying generative principles behind the creative process. In particular, to escape the paradox, we introduce creative priming (CP), wherein a trained priming model generates a prompt-specific primer that assists a response model in being creative, explicitly decoupling the creative process from response generation. The priming model l"},{"id":"arxiv:2611.10224","source":"arxiv","title":"Jais 3: Introducing Arabic-centric Agentic AI","tags":["Post-Training","LLM Training","Reasoning","Hallucination","Evaluation"],"upvotes":0,"authors":["Team IFM","Haonan Li","Hadi Abdine","Nikhil Ranjan","Mohamed Anwar","Ahmad Chamma","Amr Mohamed","Ahmed Frikha","Dani Bouch","Maaz Maqsood","George Ibrahim","Mostafa Awad","Nurkhan Laiyk","Hasan Iqbal","Abhishek Maiti","Bilal Bouardi","Shivam Chauhan","Ahmer Tabassum","Owais Aijaz","Omar Arbi","Neha Sengupta","Aaryamonvikram Singh","Abdelhakim Freihat","Sarath Chandran","Rahul Pal","Mohammed Bellam","Sajid Siddiki","Sarah AlBarri","Debopriyo Banerjee","Ali El Filali","Samta Kamboj","Rifo Genadi","Ahmed Attia","Go Inoue","Shuonan Dong","Amine Khelif Khelif","Evan Dufraisse","Florian Valade","Tapas Sen","Guowei He","Sunil Sahu","Onkar Pandit","Kareem Magdy","Sheikh Khalid bin Khalifa Al Nahyan","Samujjwal Ghosh","Zainul Abedien","Ahmed Quraishi","Larry Murray","Avraham Sheinin","Natalia Vassilieva","Preslav Nakov","Guokan Shang","Xuguang Hector Ren","Zhengzhong Liu","Eric Xing"],"pdf":"https://arxiv.org/pdf/2611.10224.pdf","arxiv":"https://arxiv.org/abs/2611.10224","url":"https://arxiv.org/abs/2611.10224","announceDate":"2026-11-10","submittedDate":"2026-11-06","topics":["Post-Training","LLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning","RL for LLM"],"date":"2026-11-10","abstract":"We present Jais 3, a fleet of six open, Arabic-centric agentic language models ranging from 0.9B to 375B parameters. Jais 3 is built to complete tasks for Arabic speakers, not only to answer questions in plain text: it is trained to plan multi-step tasks, call tools and Model Context Protocol (MCP) servers, operate a terminal, search the web, and read, edit, and produce PDF, spreadsheet, and presentation files, while communicating with the user in Arabic. Instead of pretraining from scratch, we adapt each model of the fully open K2 Horizon fleet to Arabic through continual pretraining, followed by supervised fine-tuning (SFT), final token preference optimization (FTPO), and reinforcement learning with verifiable rewards (RLVR). We combine natural Arabic text with translated, transliterated, and synthetic Arabic, and replay the base model's own training data to keep its reasoning, agentic"},{"id":"arxiv:2611.12285","source":"arxiv","title":"Learning Evidence-Grounded Reasoning for Context-Aware Time Series Forecasting","tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"authors":["Xingpeng Gao","Mingyue Cheng","Daoyu Wang","Huajian Zhang","Xiaoyu Tao"],"pdf":"https://arxiv.org/pdf/2611.12285.pdf","arxiv":"https://arxiv.org/abs/2611.12285","url":"https://arxiv.org/abs/2611.12285","announceDate":"2026-11-10","submittedDate":"2026-11-09","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"date":"2026-11-10","abstract":"LLM-driven time series forecasting has become increasingly promising by leveraging contextual features to generate future values directly or refine forecast priors. However, incorporating contextual features alone does not ensure that models can identify which features matter for forecasting and understand what they suggest about future dynamics. We argue that the fundamental challenge is how to extract predictive evidence from contextual features and when and how to leverage it to guide forecasting decisions. In this paper, we propose CastReasoner, an evidence-grounded reasoning model for context-aware time series forecasting. Specifically, CastReasoner uses a structured chain of thought (CoT) to extract predictive evidence from contextual features, infer the future dynamics suggested by this evidence, and assess these dynamics against the forecast prior to guide adaptive forecasting de"},{"id":"arxiv:2611.10045","source":"arxiv","title":"Don't Blame The Preferences: Examining The Emergence of Sycophancy in LLM Training","tags":["Post-Training","LLM Training","Evaluation","Alignment","Interpretability"],"upvotes":0,"authors":["Chao Peter Yang","Catherine Zehr","Pranav Bijith","Brandon Fain"],"pdf":"https://arxiv.org/pdf/2611.10045.pdf","arxiv":"https://arxiv.org/abs/2611.10045","url":"https://arxiv.org/abs/2611.10045","announceDate":"2026-11-10","submittedDate":"2026-11-05","topics":["Post-Training","LLM Training","Evaluation","Alignment","Interpretability","Fine-tuning"],"date":"2026-11-10","abstract":"AI sycophancy, the tendency of large language models (LLMs) to flatter users and affirm their beliefs, can undermine accuracy and contribute to misinformation, dependence, and overconfidence. Although prior work has benchmarked sycophancy in released models and proposed mitigations, its origins during training remain poorly understood. Preference alignment methods such as RLHF and DPO are often blamed, but their effects are rarely compared with earlier training stages. We investigate sycophancy across the training pipelines of three model families and three benchmarks. We find that sycophancy is largely established by the end of supervised fine-tuning (SFT), rather than introduced by preference alignment. Across all nine model benchmark combinations, SFT checkpoints attain at least 92% of preference aligned models' sycophancy scores and at least 85% of final models' scores; on average, t"},{"id":"arxiv:2611.11532","source":"arxiv","title":"DriveFoundry: Co-Evolving Data and Model for Efficient Closed-Loop Iteration in Autonomous Driving","tags":["LLM Training","VLM Training","Reasoning","Planning","Evaluation"],"upvotes":0,"authors":["Ziyang Yao","Yuncheng Jiang","Fang Li","Haochen Liu","Shaoqing Xu","Wen Zhang","Xiangyang Chu","Zibin Guo","Jiale Hou","Chuang Wan","Jia Hua","Gengzhao Xiang","Xiaoran Luo","Chong He","Yuechen Luo","Junzhe Wang","Zhiyu Sun","Jun Zhang","Wei Li","Lei Li","Hongwei Xie","Bing Wang","Yuannan Shen","Jianwei Cui","Guang Chen","Hangjun Ye","Jingwei Zhao"],"pdf":"https://arxiv.org/pdf/2611.11532.pdf","arxiv":"https://arxiv.org/abs/2611.11532","url":"https://arxiv.org/abs/2611.11532","announceDate":"2026-11-10","submittedDate":"2026-11-08","topics":["LLM Training","VLM Training","Reasoning","Planning","Evaluation","Data Engine"],"date":"2026-11-10","abstract":"A driving foundation model must learn reusable decision knowledge from rare critical events and apply it under strict runtime constraints. We introduce DriveFoundry, a closed-loop framework improving iteration efficiency under data and computation budgets by coupling structured causal data refinement with adaptive inference. The Data Engine builds traceable scene-candidate records linking scene evidence and factor-decision relations to candidate trajectories and outcome assessments. Candidate comparisons and counterfactual annotations clarify how scene factors affect behavioral feasibility and preference. Verified model failures guide VLM-assisted annotation and expert correction, refining training data and annotation systems. The model engine, Xiaomi-Drive-o1, unifies Perception, Causation, Action, World, and Value within a shared vision-language backbone to enable cross-task knowledge "},{"id":"arxiv:2611.09945","source":"arxiv","title":"A Model Organism for Studying Unverbalized Evaluation Awareness","tags":["Post-Training","LLM Training","Reasoning","Evaluation","Interpretability"],"upvotes":0,"authors":["Daniel Donnelly","Evan Chapple","Haritz Puerto","Sahar Abdelnabi"],"pdf":"https://arxiv.org/pdf/2611.09945.pdf","arxiv":"https://arxiv.org/abs/2611.09945","url":"https://arxiv.org/abs/2611.09945","announceDate":"2026-11-10","submittedDate":"2026-10-16","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Interpretability","Fine-tuning"],"date":"2026-11-10","abstract":"Large language models can recognize when they are being evaluated and change their behavior accordingly, undermining the reliability of safety benchmarks. Evaluation awareness (EA) is usually measured by having an LLM judge scan reasoning traces for explicit statements of recognition, but this signal is increasingly unreliable. Recent frontier-model system cards report a drop in verbalized rates between releases, which is indistinguishable from awareness that has gone unverbalized. Interpretability methods could detect such unverbalized evaluation awareness (UEA) in individual interactions, but lack instance-level ground truth. Asking the model alters the input, and dataset labels do not reveal whether it recognized a particular prompt as an evaluation. We address this gap with a model organism. Using synthetic document fine-tuning, SFT, and DPO, we train Qwen3.5-27B to emit a marker (a "},{"id":"arxiv:2611.12014","source":"arxiv","title":"Benchmarking language models and agents for scientific reasoning in evolving materials laboratories","tags":["Multi-Agent","Tool Use","Reasoning","Evaluation","World Model"],"upvotes":0,"authors":["Xuyu Dong","Yixuan Li","Jianguo Huang","Feng Chen","Yiyun Zhou","Bo An","Zheng Liu","Da Shu"],"pdf":"https://arxiv.org/pdf/2611.12014.pdf","arxiv":"https://arxiv.org/abs/2611.12014","url":"https://arxiv.org/abs/2611.12014","announceDate":"2026-11-10","submittedDate":"2026-11-09","topics":["Multi-Agent","Tool Use","Reasoning","Evaluation","World Model"],"date":"2026-11-10","abstract":"Large language models and the multi-agent systems built around them could accelerate materials discovery by connecting scientific knowledge with experimental decisions. Existing benchmarks establish capabilities in domain knowledge, multimodal interpretation and scientific tool use. As language models increasingly support materials research workflows, their ability to distinguish closely related material states and reason accurately with quantitative evidence remains insufficiently evaluated. These abilities are essential for comparing material responses, assessing mechanisms and maintaining reliable judgements as experimental evidence accumulates. We introduce MatScope to evaluate three connected capabilities. M1 tests unaided, condition-specific reasoning through 200 tasks spanning ten research functions, using aluminium and high-entropy alloys as representative material systems. M2 te"},{"id":"arxiv:2611.11971","source":"arxiv","title":"Harness Matters: Measuring and Dissecting Security Resilience in Web Agents","tags":["Agent Safety","Reasoning","Planning","Computer Use","Evaluation"],"upvotes":0,"authors":["Xinyi Wu","Jiagui Chen","JiaYi Dong","Geng Hong","Xudong Pan","Jiarun Dai","Mingxuan Liu","Min Yang"],"pdf":"https://arxiv.org/pdf/2611.11971.pdf","arxiv":"https://arxiv.org/abs/2611.11971","url":"https://arxiv.org/abs/2611.11971","announceDate":"2026-11-10","submittedDate":"2026-11-09","topics":["Agent Safety","Reasoning","Planning","Computer Use","Evaluation"],"date":"2026-11-10","abstract":"Web agents extend LLMs from text generation to real-world web interaction by relying on execution harnesses that interpret user goals, perceive webpages, plan actions, and ground model decisions into browser operations. While prior work has recognized that agent security depends on more than the backend model alone, how harness design quantitatively shapes web-agent security remains insufficiently measured. To systematically study web-agent harness security, we first characterize web-agent harnesses as a four-stage execution workflow covering goal interpretation, webpage perception, reasoning and planning, and action execution. Based on this abstraction, we build WebTrap Farm, a systematic and extensible evaluation framework covering three representative attack categories: malicious user prompts, malicious prompt injection, and deceptive web design. To avoid conflating security with task"},{"id":"arxiv:2611.11960","source":"arxiv","title":"Operation-aware Multimodal Clinical Decision Support System for ICU Discharge Risk Assessment","tags":["Agentic RAG","Agentic Search","Multi-Agent","Evaluation","Fine-tuning"],"upvotes":0,"authors":["Guoqing Zhang","Rafik Hadfi","Takayuki Ito"],"pdf":"https://arxiv.org/pdf/2611.11960.pdf","arxiv":"https://arxiv.org/abs/2611.11960","url":"https://arxiv.org/abs/2611.11960","announceDate":"2026-11-10","submittedDate":"2026-11-09","topics":["Agentic RAG","Agentic Search","Multi-Agent","Evaluation","Fine-tuning"],"date":"2026-11-10","abstract":"Unplanned 30-day intensive care unit (ICU) readmission is a critical benchmark for evaluating healthcare quality. Most predictive models assume readmission risk depends solely on a patient's individual pathophysiological state, ignoring hospital operational context and resource capacity. In practice, discharge decisions are dynamic trade-offs between patient stability and bed turnover pressures. To address this gap, we develop an Operation-aware Multimodal Clinical Decision Support System (CDSS) for ICU discharge risk assessment. The system combines multi-agent collaborative extraction with self-evolving retrieval-augmented generation (RAG) to eliminate template noise from progress notes, while constructing departmental workload indicators alongside admission flow features, continuous vital signs, and sparse medical codes (ICD/DRG). Addressing severe class imbalance (about 10.5% readmiss"},{"id":"arxiv:2611.11330","source":"arxiv","title":"When Credit Turns Against Tools: Transition-Aware Credit Assignment in Agentic Reinforcement Learning","tags":["Post-Training","Tool Use","Reasoning","Evaluation","RL for LLM"],"upvotes":0,"authors":["Xiangyu Lu","Zhanke Zhou","Jiazhe Ning","Chentao Cao","Jiangchao Yao","Bo Han"],"pdf":"https://arxiv.org/pdf/2611.11330.pdf","arxiv":"https://arxiv.org/abs/2611.11330","url":"https://arxiv.org/abs/2611.11330","announceDate":"2026-11-10","submittedDate":"2026-11-08","topics":["Post-Training","Tool Use","Reasoning","Evaluation","RL for LLM"],"date":"2026-11-10","abstract":"Agentic reinforcement learning with verifiable rewards trains language models through multi-turn tool interactions, yet their reasoning performance and tool-calling ability can decline during training. We trace this degradation to three coupled mechanisms: (1) tool-token imbalance produces negative overall tool credit when incorrect trajectories contain more tool tokens per turn than correct ones; (2) aggregation amplification can further strengthen this negative signal as token-mean aggregation gives longer incorrect trajectories greater weight in policy updates; and (3) failure-driven retries prolong trajectories as models tend to call tools again after execution errors, extending potential negative credit to recovery attempts. To counter this suppression, we propose Transition-Aware Credit Assignment (TACA), which targets the transition from reasoning to tool use through supervision o"},{"id":"arxiv:2611.10844","source":"arxiv","title":"What Broke & Why: Practical Lessons from Reinforcement Learning Post-Training","tags":["Agentic Search","Post-Training","Reasoning","Evaluation","RL for LLM"],"upvotes":0,"authors":["Luv Verma"],"pdf":"https://arxiv.org/pdf/2611.10844.pdf","arxiv":"https://arxiv.org/abs/2611.10844","url":"https://arxiv.org/abs/2611.10844","announceDate":"2026-11-10","submittedDate":"2026-11-07","topics":["Agentic Search","Post-Training","Reasoning","Evaluation","RL for LLM"],"date":"2026-11-10","abstract":"Reinforcement learning with verifiable rewards (RLVR) has become an important way to improve how language models reason, solve problems, and use tools. But getting it to work in practice is not always straightforward. Training can fail because a model receives no useful reward, learns to exploit the reward system, stops exploring, or appears to improve when the evaluation itself is misleading. In this book, we give a practical introduction to reinforcement learning post-training for language models, focusing on what works, what fails, and why. We begin with the foundations of post-training, explain GRPO and the training loop step by step, and then follow five training programs covering math reasoning, search agents, training stability, mixture-of-experts models, and software engineering tasks. Each program shows the problems encountered, the changes made, and the lessons learned. The boo"},{"id":"arxiv:2611.10768","source":"arxiv","title":"BlenderFORGE: Framework for Optimizing Reactive 3D-Graphics Editing Ability of MLLMs","tags":["LLM Training","Code Agent","Evaluation","Fine-tuning","RL for LLM"],"upvotes":0,"authors":["Zilin Guo","Tianrui Zhang","Yi Rong","Yichen Liu","Yuxin Guo","Jingcheng Ni","Lewei Lu","Zehuan Wu","Dan Xu"],"pdf":"https://arxiv.org/pdf/2611.10768.pdf","arxiv":"https://arxiv.org/abs/2611.10768","url":"https://arxiv.org/abs/2611.10768","announceDate":"2026-11-10","submittedDate":"2026-11-07","topics":["LLM Training","Code Agent","Evaluation","Fine-tuning","RL for LLM"],"date":"2026-11-10","abstract":"Multimodal Large Language Models (MLLMs) have shown promise as interactive agents, yet precise, programmatic 3D graphics editing remains difficult to train because existing systems largely rely on closed-source model APIs and lack deterministic, state-verifiable execution environments. We present BlenderFORGE, a trainable data-environment-optimization framework for open-weight MLLM agents that edit explicit Blender scenes through Blender Python (bpy) code generation. BlenderFORGE targets four fundamental state-verifiable editing task families: object placement, shape-key editing, lighting adjustment, and material modification. It integrates three components: (1) a scalable perturbation-based data generation pipeline built from curated assets and large-scale 3D scene repositories; (2) an isolated Blender Sandbox for deterministic code execution, structured state export, and closed-loop re"},{"id":"arxiv:2611.10411","source":"arxiv","title":"Tail-risk-aware Agent Safety: Constraining Tail Risks Across Multi-step LLM Agent Workflows","tags":["Agent Safety","Post-Training","Planning","Evaluation","Alignment"],"upvotes":0,"authors":["Shilong Pan","Zhiliang Tian","Zihan Chen","Wentao Zou","Weiguo Chen","DongSheng Li"],"pdf":"https://arxiv.org/pdf/2611.10411.pdf","arxiv":"https://arxiv.org/abs/2611.10411","url":"https://arxiv.org/abs/2611.10411","announceDate":"2026-11-10","submittedDate":"2026-11-07","topics":["Agent Safety","Post-Training","Planning","Evaluation","Alignment"],"date":"2026-11-10","abstract":"LLM-based agents extend LLMs with tool calls, memory, planning, and retrieval to act in external environments, but they are vulnerable to attacks at different workflow steps. Existing defenses, including prompt engineering and post-training alignment, primarily improve LLM-only safety and often overlook risks that arise from multi-step execution. External verification adds guardrails to check each step separately, but it typically ignores how risks can propagate across steps. We argue that we should consider risk transitions across dependent steps through the agent workflow, rather than separate verification on a single step. In this paper, we propose \\textbf{T}ail-risk-aware \\textbf{A}gent \\textbf{S}afety (TAS), a tail-risk-aware safety framework that models agent workflow safety as a sequence of dependent safety states and constrains the rare but extreme risks (i.e., tail risk) with a "},{"id":"arxiv:2611.11771","source":"arxiv","title":"ARMOR: Adaptive Curriculum Meta-Learning for Noise-Robust RAG Reasoning","tags":["Agentic RAG","Agentic Search","Post-Training","Reasoning","Hallucination"],"upvotes":0,"authors":["Yan Wang","Yuxin Zhang","Shenyu Zhang","Yongrui Chen","Sheng Bi","Guilin Qi"],"pdf":"https://arxiv.org/pdf/2611.11771.pdf","arxiv":"https://arxiv.org/abs/2611.11771","url":"https://arxiv.org/abs/2611.11771","announceDate":"2026-11-10","submittedDate":"2026-11-09","topics":["Agentic RAG","Agentic Search","Post-Training","Reasoning","Hallucination"],"date":"2026-11-10","abstract":"Retrieval-Augmented Generation (RAG) systems have demonstrated remarkable effectiveness in mitigating hallucinations by incorporating external knowledge. However, the retrieval process inevitably introduces noise, posing significant challenges to RAG robustness. Fundamentally, noise robustness is a composite competency encompassing noise identification, retrieval filtering, and robust reasoning. Unfortunately, existing methods often fail to capture this holistic nature, typically restricted to single-dimensional enhancements or hampered by noise-induced optimization interference. To address these limitations, we decompose RAG robustness into three sub-tasks: knowledge boundary perception, retrieval verification, and robust reasoning. Accordingly, we propose ARMOR, an Adaptive Curriculum Meta-Learning for Noise Robust RAG Reasoning. Inspired by the teaching process, ARMOR introduces an ad"},{"id":"arxiv:2611.10089","source":"arxiv","title":"META-IR: Meta-Introspective Reasoning for Adaptive Safety Alignment in LLM","tags":["Agent Safety","Reasoning","Evaluation","Alignment","Reflection"],"upvotes":0,"authors":["Mahabubur Rahman Miraj","Hongyu Huang","Nankun Mu","Chao Chen","Shanqin Yi"],"pdf":"https://arxiv.org/pdf/2611.10089.pdf","arxiv":"https://arxiv.org/abs/2611.10089","url":"https://arxiv.org/abs/2611.10089","announceDate":"2026-11-10","submittedDate":"2026-11-06","topics":["Agent Safety","Reasoning","Evaluation","Alignment","Reflection"],"date":"2026-11-10","abstract":"Large Language Models (LLMs) remain vulnerable to jailbreak attacks and harmful-content prompts, particularly under adversarial distribution shifts where static alignment pipelines fail to generalize. Although introspective methods such as STAIR strengthen refusal consistency, they depend on fixed self-evaluation policies that cannot rapidly adapt to evolving manipulation strategies. To overcome these limitations, this paper introduces META-IR, a meta-introspective reasoning framework that enhances safety alignment through meta-learning-driven adaptation. It employs a dual-loop architecture: an inner introspective loop that performs structured risk analysis, self-assessment, and reflective correction via SI-MCTS, and an outer meta-learning loop that optimizes the introspection policy across diverse jailbreak task families to enable rapid generalization to unseen attacks. A dynamic jailbr"},{"id":"arxiv:2611.12311","source":"arxiv","title":"MNN-Pocket-0.3B Technical Report","tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"authors":["MNN Team"],"pdf":"https://arxiv.org/pdf/2611.12311.pdf","arxiv":"https://arxiv.org/abs/2611.12311","url":"https://arxiv.org/abs/2611.12311","announceDate":"2026-11-10","submittedDate":"2026-11-09","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"date":"2026-11-10","abstract":"This technical report presents MNN-Pocket-0.3B, a compact 300M-parameter dense language model designed for efficient on-device deployment and supporting context lengths of up to 32K tokens. With an INT4 deployment footprint of only 173 MB and decoding throughput of up to 466 tokens/s on iPad Pro M5 (Metal), it can be seamlessly integrated into applications on edge devices such as smartphones and smart glasses. MNN-Pocket-0.3B is developed through the co-design of its architecture, data, training pipeline, and inference system. Hardware-aware architecture selection and dependency-aware vocabulary pruning balance model capability with on-device memory and compute constraints. A four-stage pre-training pipeline covering approximately 4.1 trillion high-quality Chinese and English tokens equips the model with broad knowledge and reasoning capabilities. This is followed by a three-stage post-t"},{"id":"arxiv:2611.10463","source":"arxiv","title":"LongCapHarness: Capability-Guided Auto-Harnessing for Long-Context Reasoning","tags":["Post-Training","Reasoning","Evaluation","Reflection","Data Engine"],"upvotes":0,"authors":["Tao Zhang","Yuhang He"],"pdf":"https://arxiv.org/pdf/2611.10463.pdf","arxiv":"https://arxiv.org/abs/2611.10463","url":"https://arxiv.org/abs/2611.10463","announceDate":"2026-11-10","submittedDate":"2026-11-07","topics":["Post-Training","Reasoning","Evaluation","Reflection","Data Engine"],"date":"2026-11-10","abstract":"Existing methods enhancing an LLM's long-context reasoning capability often rely on data synthesis and follow-up LLM post-training. However, the data synthesis strategy and the post-training recipes are empirically driven and computationally intensive. In this work, we propose a new framework, dubbed LongCapHarness, to instead harness the underlying capabilities for long-context reasoning. The harnessing process recursively revises and updates capability primitive implementation, capability state and control logic through recursive self-improvement on the development set. With neither data synthesis nor LLM post-training, LongCapHarness is applied to Llama3-8B and transferred to Qwen2.5-3B. LongCapHarness substantially outperforms recent data-synthesis-based baselines on HELMET and RULER benchmarks; its estimated development cost is less than 50% of the estimated training costs of NExtLo"},{"id":"arxiv:2611.10908","source":"arxiv","title":"Beyond Real or Fake: A Dual-Channel Authenticity and Reasoning Protocol for Photographic Assessment","tags":["VLM Training","Reasoning","Evaluation","Alignment","Fine-tuning"],"upvotes":0,"authors":["Xiaoxiao Li","Ruinan Jin","Lili Meng","Miaosen Wang","Athula Balachandran","Pei Cao"],"pdf":"https://arxiv.org/pdf/2611.10908.pdf","arxiv":"https://arxiv.org/abs/2611.10908","url":"https://arxiv.org/abs/2611.10908","announceDate":"2026-11-10","submittedDate":"2026-11-07","topics":["VLM Training","Reasoning","Evaluation","Alignment","Fine-tuning"],"date":"2026-11-10","abstract":"Forensic verification has converged on a binary \"real vs. fake\" label that confates fully synthetic, tampered, and AI-retouched images despite their very different consequences. We argue that GenAI manipulations decompose along two complementary channels: a camera channel of sensor fingerprints (destroyed by neural processing), and a semantic channel of scene-level coherence (disrupted by content edits). Each manipulation type leaves a distinctive two-channel signature. We instantiate this taxonomy in 2CAP (2-Channel Authenticity Protocol), pairing a contrastively-trained camera encoder with a frozen semantic encoder to serve two applications on a shared backbone: (i) four-class authenticity classification via cross-attention fusion with learnable reliability weights; and (ii) evidence generation, where an authentic image serves as a reference for a query and the two encoders produce per"},{"id":"arxiv:2611.10831","source":"arxiv","title":"Multimodal Models Can See, But Can They Think? A Study of Turkish Visual Reasoning","tags":["LLM Training","VLM Training","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"authors":["Berke Bunyamin Sule","Yavuz Selim Aygan","Ahmed Zeer","Elif Ince","Ali Mert Temizsoy","Ozgur Agar","Himmet Toprak Kesgin","Muzaffer Kaan Yuce","Mehmet Fatih Amasyali"],"pdf":"https://arxiv.org/pdf/2611.10831.pdf","arxiv":"https://arxiv.org/abs/2611.10831","url":"https://arxiv.org/abs/2611.10831","announceDate":"2026-11-10","submittedDate":"2026-11-07","topics":["LLM Training","VLM Training","Reasoning","Evaluation","Fine-tuning"],"date":"2026-11-10","abstract":"Vision-Language Models have had massive leaps in recent years. Yet, when tested on high-level cognitive tasks like pattern completion, abstract logic, and relational reasoning, they still fall short. This limitation stems from the models' lack of ability to find out underlying rules and maintain constant intermediate steps, rather than merely deciding on the correct option. To research these shortcomings, this study analyzes visual reasoning performance throughout a multilingual evaluation framework encompassing the BİLSEM, MM-IQ, Visual Puzzles, and PuzzleVQA datasets. We evaluate various data mixing strategies and supervised fine-tuning (SFT) methods. We observed that a correct answer does not always mean the reasoning chain is valid. Because of this, we adopt an LLM-as-a-Judge approach to assess the quality of reasoning beyond final answer accuracy. Our experimental results reveal tha"},{"id":"arxiv:2611.10720","source":"arxiv","title":"Locating and Repairing Domain Shift in VLM Trajectory Planning","tags":["VLM Training","Planning","Evaluation","Alignment","Fine-tuning"],"upvotes":0,"authors":["Zhihong Cui","Hengyu Liu","Michael Alexander Riegler","Guandong Xu","Amir Taherkordi","Tor Skeie"],"pdf":"https://arxiv.org/pdf/2611.10720.pdf","arxiv":"https://arxiv.org/abs/2611.10720","url":"https://arxiv.org/abs/2611.10720","announceDate":"2026-11-10","submittedDate":"2026-11-07","topics":["VLM Training","Planning","Evaluation","Alignment","Fine-tuning"],"date":"2026-11-10","abstract":"Vision-Language Models (VLMs) are increasingly adopted as end-to-end driving planners, yet they suffer from cross-city domain shift. Existing methods treat this shift as a single quantity addressed by uniform alignment or single-site editing. We challenge this view on two counts: (i) domain shift in VLM trajectory planners is inherently structured across modality and layer, and (ii) a locate-then-repair recipe matched to this structure outperforms every uniform-objective baseline. We analyse domain shift via activation patching and uncover two regularities. (F1) Modality axis. Image and text tokens exhibit distinct shift patterns in each VLM. (F2) Layer axis. The layer-wise shift partition is architecture-dependent and dataset-stable. These findings recast domain shift as a two-dimensional tensor indexed by modality (image vs. text tokens) and layer, motivating a simple principle: locate"},{"id":"arxiv:2611.12269","source":"arxiv","title":"Agent4Crypto: A Dual-Reflective and Market-Feedback-Aligned LLM-Based Multi-Agent System for Cryptocurrency Trading","tags":["Multi-Agent","Reasoning","Reflection","RL for LLM"],"upvotes":0,"authors":["Guangyan Gan","Jiahao Li","Jiashun Wang","Lin William Cong"],"pdf":"https://arxiv.org/pdf/2611.12269.pdf","arxiv":"https://arxiv.org/abs/2611.12269","url":"https://arxiv.org/abs/2611.12269","announceDate":"2026-11-10","submittedDate":"2026-11-09","topics":["Multi-Agent","Reasoning","Reflection","RL for LLM"],"date":"2026-11-10","abstract":"Cryptocurrency markets provide a natural testbed for autonomous AI agents because they are digital-native, high-frequency, and machine-speed environments, yet existing methods often struggle with non-stationary market regimes, opaque decisions, and fixed aggregation rules. In this paper, we propose Agent4Crypto, a dual-reflective and market-feedback-aligned multi-agent system. The framework coordinates specialized agents for data collection, analysis, risk assessment, reflection, and trading, synthesizing heterogeneous signals from prices, indicators, news, and charts in an interpretable decision pipeline. Our central design is a trader-centric decision mechanism: three style-specific trader agents, Aggressive, Neutral, and Conservative, generate candidate actions and natural-language rationales from the same market context, while their influence is learned rather than manually fixed. A "},{"id":"arxiv:2611.12164","source":"arxiv","title":"Let the Fixer Decide: Training a Code Localizer from the Fixer's Likelihood","tags":["LLM Training","Code Agent","Evaluation","Fine-tuning"],"upvotes":0,"authors":["Khalil Hennara","Muhammad Hreden","Zeina Aldallal","Sara Chrouf","Safwan AlModhayan"],"pdf":"https://arxiv.org/pdf/2611.12164.pdf","arxiv":"https://arxiv.org/abs/2611.12164","url":"https://arxiv.org/abs/2611.12164","announceDate":"2026-11-10","submittedDate":"2026-11-09","topics":["LLM Training","Code Agent","Evaluation","Fine-tuning"],"date":"2026-11-10","abstract":"Code localizers are usually trained to predict the files a reference patch edits, but the code a fixer needs to read is not the same as the code it changes. We propose Fixer-Guided Localization (FGL): the localizer proposes several localizations, a frozen fixer scores each by how likely it makes a verified patch, and the localizer is trained on these scores with weighted supervised fine-tuning, without running tests and without reinforcement learning. We build the full pipeline on Gemma 4 E4B for the Kaggle Gemma-4 Developer Agent competition, from 1,629 test-verified Kimi K3 trajectories. The FGL target helps the fixer find the bug as often as the teacher's localization while using 27.5% less code. On the development set, one EM round moves the agent in the expected direction compared with a matched control: more tasks reach a patch (53 vs. 46), fewer tasks get stuck reading files that "}],"archive":[],"latestPath":"data/latest.json"};
